#define AUDIO_SUCCESS 0
#define AUDIO_EPARAM 1
#define codec_reg_set(...) qa_codec_set(s,__VA_ARGS__)
#define msleep(ms) qa_pause(s,(ms)*1000u)
#define printk(...) ((void)0)
#define TS_CODEC_CGR_00			0x00
#define TS_CODEC_CACR_02		0x08
#define TS_CODEC_CACR2_03       0x0c
#define TS_CODEC_CDCR1_04       0x10
#define TS_CODEC_CDCR2_05       0x14
#define TS_CODEC_CAVR_08        0x20
#define TS_CODEC_CGAINLR_09     0x24
#define TS_CODEC_POWER_20       0x80
#define TS_CODEC_CCR_21         0x84
#define TS_CODEC_CAACR_22       0x88
#define TS_CODEC_CMICCR_23      0x8c
#define TS_CODEC_CMICGAINR_24   0x90
#define TS_CODEC_CALCGR_25      0x94
#define TS_CODEC_CANACR_26      0x98
#define TS_CODEC_CANACR2_27     0x9c
#define TS_CODEC_CHR_28         0xA0
#define TS_CODEC_CMR_40			0x100
#define TS_CODEC_CTR_41			0x104
#define TS_CODEC_CAGCCR_42		0x108
#define TS_CODEC_CPGR_43		0x10c
#define TS_CODEC_CSRR_44		0x110
#define TS_CODEC_CALMR_45		0x114
#define TS_CODEC_CAHMR_46		0x118
#define TS_CODEC_CALMINR_47		0x11c
#define TS_CODEC_CAHMINR_48		0x120
#define TS_CODEC_CAFG_49		0x124
#define TS_CODEC_CCAGVR_4c		0x130
static int qa_codec_disable_playback(struct qa_state *s)
{
	/* QC5 spk_gpio=-1; no GPIO access. */
	codec_reg_set(TS_CODEC_CHR_28, 0, 4, 0);
	msleep(10);
	codec_reg_set(TS_CODEC_CHR_28, 7, 7, 0);
	msleep(10);
	codec_reg_set(TS_CODEC_CHR_28, 6, 6, 0);
	msleep(10);
	codec_reg_set(TS_CODEC_CHR_28, 5, 5, 0);
	msleep(10);
	codec_reg_set(TS_CODEC_CANACR2_27, 5, 5, 0);
	msleep(10);
	codec_reg_set(TS_CODEC_CANACR2_27, 6, 6, 0);
	msleep(10);
	codec_reg_set(TS_CODEC_CANACR2_27, 7, 7, 0);
	msleep(10);
	codec_reg_set(TS_CODEC_CANACR_26, 3, 3, 0);
	msleep(10);
	codec_reg_set(TS_CODEC_CANACR2_27, 4, 4, 0);
	msleep(10);

    return AUDIO_SUCCESS;
}

static int qa_codec_init(struct qa_state *s)
{
	int i = 0;
	char value = 0;
	codec_reg_set(TS_CODEC_CGR_00, 0, 1, 0);
	msleep(10);
	codec_reg_set(TS_CODEC_CGR_00, 0, 1, 0x3);
	msleep(10);
	/* Choose DAC I2S Master Mode */
	codec_reg_set(TS_CODEC_CACR2_03, 0, 7, 0x3e);
	codec_reg_set(TS_CODEC_CDCR1_04, 0, 7, 0x10);//DAC I2S interface is I2S Mode.
	codec_reg_set(TS_CODEC_CDCR2_05, 0, 7, 0x3e);

	codec_reg_set(TS_CODEC_CANACR_26, 0, 1, 0x1);
	msleep(10);
	codec_reg_set(TS_CODEC_CCR_21, 0, 6, 0x1);
	msleep(10);
	codec_reg_set(TS_CODEC_CAACR_22, 5, 5, 1);//setup reference voltage
	msleep(10);
	for (i = 0; i <= 6; i++) {
		value |= value<<1 | 1;
		codec_reg_set(TS_CODEC_CCR_21, 0, 6, value);
		msleep(30);
	}
	msleep(20);

	codec_reg_set(TS_CODEC_CGR_00, 1, 1, 0);
	codec_reg_set(TS_CODEC_CGR_00, 1, 1, 1);
	return 0;
}

static int qa_codec_enable_record(struct qa_state *s)
{
	/* enable POP sound control, low vcm power */
	codec_reg_set(TS_CODEC_CANACR_26, 0, 1, 0x2);
	msleep(10);

	/* enable hpf and set mode 0 */
	codec_reg_set(TS_CODEC_CGAINLR_09, 0, 4, 0x8);
	msleep(10);
	/* Choose ADC I2S interface mode */
	codec_reg_set(TS_CODEC_CACR_02, 3, 4, 0x2);
	msleep(10);
	codec_reg_set(TS_CODEC_CACR_02, 7, 7, 0x1);
	msleep(10);
	/* Choose ADC I2S Master Mode */
	codec_reg_set(TS_CODEC_CACR2_03, 0, 7, 0x3e);
	msleep(10);

	/* Enable ADC */
	codec_reg_set(TS_CODEC_CMICCR_23, 7, 7, 0x1);
	msleep(10);
	codec_reg_set(TS_CODEC_CAACR_22, 4, 4, 0x1);
	msleep(10);
	codec_reg_set(TS_CODEC_CAACR_22, 3, 3, 0x1);   //micbias enable
	msleep(10);
	codec_reg_set(TS_CODEC_CAACR_22, 0, 2, 0x7);   //micbias
	msleep(10);
	codec_reg_set(TS_CODEC_CMICCR_23, 5, 5, 0x1);  //ref voltage
	msleep(10);
	codec_reg_set(TS_CODEC_CMICGAINR_24, 4, 4, 0x1);
	msleep(10);
	codec_reg_set(TS_CODEC_CMICGAINR_24, 5, 5, 0x1);
	msleep(10);
	codec_reg_set(TS_CODEC_CANACR_26, 6, 6, 0x1);
	msleep(10);
	codec_reg_set(TS_CODEC_CANACR_26, 5, 5, 0x1);
	msleep(10);
	codec_reg_set(TS_CODEC_CANACR_26, 4, 4, 0x1);
	msleep(10);
	codec_reg_set(TS_CODEC_CANACR_26, 7, 7, 0x1);
	msleep(10);
	codec_reg_set(TS_CODEC_CMICCR_23, 6, 6, 0x1);
	msleep(10);
	codec_reg_set(TS_CODEC_CMICGAINR_24, 6, 7, 2); /* QC5 original microphone hardware gain. */ //mic hw gain
	msleep(10);
	codec_reg_set(TS_CODEC_CALCGR_25, 0, 4, 0x10);
	msleep(10);

	/* low power consumption */
	codec_reg_set(TS_CODEC_CCR_21, 0, 6, 0x1);
	msleep(11);

	return 0;
}

static int qa_codec_set_sample_rate(struct qa_state *s, unsigned int rate)
{
	int i = 0;
	unsigned int mrate[8] = {8000, 12000, 16000, 24000, 32000, 44100, 48000, 96000};
	unsigned int rate_fs[8] = {7, 6, 5, 4, 3, 2, 1, 0};
	for (i = 0; i < 8; i++) {
		if (rate <= mrate[i])
			break;
	}
	if (i == 8)
		i = 0;
	codec_reg_set(TS_CODEC_CSRR_44, 0, 2, rate_fs[i]);

	return 0;
}

static int qa_codec_record_set_again(struct qa_state *s, int channel, int gain)
{
	/******************************************\
	| vol :0	1		2	..	30  31	       |
	| gain:-18  -16.5  -15	..	27  28.5 (+DB) |
	\******************************************/
	int analog_gain = 0;
	if(!s)	
		return -AUDIO_EPARAM;
	analog_gain = gain < 0 ? 0 : (gain > 0x1f ? 0x1f : gain);
	//printk("begain to set codec again\n");
	codec_reg_set(TS_CODEC_CAFG_49, 6, 6, 0);
	msleep(10);
	codec_reg_set(TS_CODEC_CALCGR_25, 0, 4, analog_gain);
	msleep(10);
	return 0;
}
#undef AUDIO_SUCCESS
#undef AUDIO_EPARAM
#undef codec_reg_set
#undef msleep
#undef printk
